var EVENTS;

(function boot() {
  function tryFetch(url) {
    return fetch(url).then(function(r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      var ct = (r.headers.get("content-type") || "").toLowerCase();
      if (ct.indexOf("html") !== -1) {
        throw new Error("Server returned HTML instead of JSON for " + url);
      }
      return r.json();
    });
  }

  // Try canonical data/events.json first, then root events.json, then Windows backslash zip fallback
  tryFetch("data/events.json")
    .catch(function() {
      return tryFetch("events.json");
    })
    .catch(function() {
      return tryFetch("data%5Cevents.json");
    })
    .then(function(data) {
      EVENTS = data;
      initApp();
    })
    .catch(function(err) {
      document.getElementById("mapStatus").innerHTML =
        '<b style="color:#dc2626">Data load failed:</b> ' + err.message;
      console.error("Boot failed:", err);
    });
})();

